syntax = "proto3";

package chile.comunes;


// Estado civil de una persona.
enum EstadoCivil {
  ESTADO_CIVIL_UNSPECIFIED = 0;
  ESTADO_CIVIL_SOLTERO = 1;
  ESTADO_CIVIL_CASADO = 2;
  ESTADO_CIVIL_VIUDO = 3;
  ESTADO_CIVIL_DIVORCIADO = 4;
  ESTADO_CIVIL_ACUERDO_UNION_CIVIL = 5;
}

// Domicilio postal o residencial.
message Direccion {
  // Nombre de la calle, pasaje o camino.
  string calle = 1;
  optional string numero = 2;
  string comuna = 3;
  int32 region = 4;
}

// Datos de contacto de una persona.
message Contacto {
  optional string email = 1;
  repeated string telefonos = 2;
}

// Persona natural.
message Persona {
  string rut = 1;
  string nombres = 2;
  string apellidos = 3;
  optional EstadoCivil estadoCivil = 4;
  optional Direccion domicilio = 5;
  optional Contacto contacto = 6;
}

